css:
[data-bz-section="cta-band"] > .bz-section { padding-block: 80px }
[data-bz-section="cta-band"] > .bz-section > .bz-container { max-width: calc(var(--container) + 2 * var(--container-pad)) }
[data-bz-section="cta-band"] .bz-eyebrow { color: #A0A0A0; text-align: center; margin-bottom: 18px }
[data-bz-section="cta-band"] h2 { font-size: 28px; line-height: 1.6; margin: 0 0 18px; color: #fff }
[data-bz-section="cta-band"] [data-bz-node="cta-body"] .bz-text { margin-inline: auto; max-width: 620px }
[data-bz-section="cta-band"] [data-bz-node="cta-body"] p { color: #C7C1B4; font-size: 15px; line-height: 1.7; margin: 0 auto 30px }
[data-bz-section="cta-band"] .bz-btns { justify-content: center; margin-block: 0; gap: 14px }
[data-bz-section="cta-band"] .bz-btn { min-height: 48px; padding: 0 26px }
[data-bz-section="cta-band"] [data-bz-node="cta-note"] .bz-text { margin-inline: auto }
[data-bz-section="cta-band"] [data-bz-node="cta-note"] p { color: #A0A0A0; font-size: 13px; margin-top: 22px }
[data-bz-section="cta-band"] .bz-btn--secondary { background: transparent; color: #fff; border-color: #fff }
[data-bz-section="cta-band"] .bz-btn--secondary:hover { background: rgba(255,255,255,.08) }
@media (max-width: 640px) { [data-bz-section="cta-band"] > .bz-section { padding-block: 56px } }
